=== FILE: apb_gpio.v ===
// apb_gpio.v
// APB4 GPIO peripheral with interrupts.
// Implements microarchitecture.md (approved) for interface_spec.md (approved).
// Requirement: Create an APB GPIO peripheral with interrupts.
`default_nettype none

module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Register index, paddr[5:2]
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // Bits 0 .. N-1 set: the pins that exist
  localparam [31:0] PINS = {32{1'b1}} >> (32 - N);

  // State
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;
  reg [31:0] rise_q;
  reg [31:0] fall_q;
  reg [31:0] high_q;
  reg [31:0] low_q;
  reg [31:0] inten_q;
  reg [31:0] status_q;

  // Next state
  reg [31:0] data_out_d;
  reg [31:0] dir_d;
  reg [31:0] rise_d;
  reg [31:0] fall_d;
  reg [31:0] high_d;
  reg [31:0] low_d;
  reg [31:0] inten_d;
  reg [31:0] status_d;
  reg [31:0] clear;
  reg [31:0] in_w;

  // APB decode: zero wait states, access = completing cycle
  wire       access     = psel & penable;
  wire [3:0] idx        = paddr[5:2];
  wire       aligned    = (paddr[1:0] == 2'b00);
  wire       upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire       mapped     = aligned & upper_zero & (idx <= IDX_INTR_STATUS);
  wire       ro_write   = pwrite & (idx == IDX_DATA_IN);
  wire       wr_ok      = access & pwrite & mapped & ~ro_write;
  wire       rd_ok      = access & ~pwrite & mapped;

  // Write mask: byte strobes expanded, limited to existing pins
  wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
  wire [31:0] wmask     = strb_mask & PINS;
  wire [31:0] wbits     = pwdata & wmask;

  // Detection from the two samples and the enables before the edge
  wire [31:0] rise_ev  = in_q & ~in_prev_q;
  wire [31:0] fall_ev  = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q) |
                          (in_q & high_q) | (~in_q & low_q)) & PINS;

  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | ro_write);
  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & inten_q);

  // Input sample widened to 32 bits, zeros above N
  always @* begin
    in_w        = 32'h0000_0000;
    in_w[N-1:0] = gpio_in;
  end

  // Next-state logic
  always @* begin
    data_out_d = data_out_q;
    dir_d      = dir_q;
    rise_d     = rise_q;
    fall_d     = fall_q;
    high_d     = high_q;
    low_d      = low_q;
    inten_d    = inten_q;
    clear      = 32'h0000_0000;
    if (wr_ok) begin
      case (idx)
        IDX_DATA_OUT:    data_out_d = (data_out_q & ~wmask) | wbits;
        IDX_DIR:         dir_d      = (dir_q      & ~wmask) | wbits;
        IDX_INTR_RISE:   rise_d     = (rise_q     & ~wmask) | wbits;
        IDX_INTR_FALL:   fall_d     = (fall_q     & ~wmask) | wbits;
        IDX_INTR_HIGH:   high_d     = (high_q     & ~wmask) | wbits;
        IDX_INTR_LOW:    low_d      = (low_q      & ~wmask) | wbits;
        IDX_INTR_ENABLE: inten_d    = (inten_q    & ~wmask) | wbits;
        IDX_INTR_STATUS: clear      = wbits;
        default:         clear      = 32'h0000_0000;
      endcase
    end
    // The OR with detected comes last: a detection beats a clear.
    status_d = (status_q & ~clear) | detected;
  end

  // Registers: synchronous active-low reset
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0000_0000;
      dir_q      <= 32'h0000_0000;
      in_q       <= 32'h0000_0000;
      in_prev_q  <= 32'h0000_0000;
      rise_q     <= 32'h0000_0000;
      fall_q     <= 32'h0000_0000;
      high_q     <= 32'h0000_0000;
      low_q      <= 32'h0000_0000;
      inten_q    <= 32'h0000_0000;
      status_q   <= 32'h0000_0000;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      in_q       <= in_w;
      in_prev_q  <= in_q;
      rise_q     <= rise_d;
      fall_q     <= fall_d;
      high_q     <= high_d;
      low_q      <= low_d;
      inten_q    <= inten_d;
      status_q   <= status_d;
    end
  end

  // Read data: zero unless a mapped read access
  always @* begin
    prdata = 32'h0000_0000;
    if (rd_ok) begin
      case (idx)
        IDX_DATA_OUT:    prdata = data_out_q;
        IDX_DIR:         prdata = dir_q;
        IDX_DATA_IN:     prdata = in_q;
        IDX_INTR_RISE:   prdata = rise_q;
        IDX_INTR_FALL:   prdata = fall_q;
        IDX_INTR_HIGH:   prdata = high_q;
        IDX_INTR_LOW:    prdata = low_q;
        IDX_INTR_ENABLE: prdata = inten_q;
        IDX_INTR_STATUS: prdata = status_q;
        default:         prdata = 32'h0000_0000;
      endcase
    end
  end

`ifdef FORMAL
  // Design-intent assertions (no proof job is submitted with this RTL).
  always @(*) begin
    assert (pready == 1'b1);
    if (!access) assert (pslverr == 1'b0);
    if (!rd_ok)  assert (prdata == 32'h0000_0000);
    assert ((status_q & ~PINS) == 32'h0000_0000);
    assert ((data_out_q & ~PINS) == 32'h0000_0000);
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
// apb_gpio_tb.v
// Self-checking testbench for apb_gpio (interface_spec.md section 8).
// Two DUTs (N=8 and N=32) share one APB bus; each has an independent
// cycle-by-cycle reference model checked on every clock edge, and the
// directed sequence also checks literal expected values.
`default_nettype none

module apb_gpio_tb;
  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] gin;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gout8;
  wire [7:0]  goe8;
  wire [31:0] gout32;
  wire [31:0] goe32;
  wire        irq8;
  wire        irq32;

  wire [31:0] m8_prdata;
  wire [31:0] m32_prdata;
  wire [31:0] m8_out;
  wire [31:0] m8_oe;
  wire [31:0] m32_out;
  wire [31:0] m32_oe;
  wire        m8_err;
  wire        m32_err;
  wire        m8_irq;
  wire        m32_irq;

  integer passed;
  integer failed;
  integer mpassed = 0;
  integer mfailed = 0;
  integer step;
  integer got_nonce;
  integer k;
  reg     mon_en = 1'b0;
  reg [8*64-1:0] nonce;
  reg [7:0] a;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
    .pslverr(pslverr8), .gpio_in(gin[7:0]), .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8));

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
    .pslverr(pslverr32), .gpio_in(gin), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32));

  apb_gpio_tb_model #(.N(8)) mdl8 (
    .clk(pclk), .rstn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .pin(gin),
    .e_prdata(m8_prdata), .e_pslverr(m8_err), .e_out(m8_out), .e_oe(m8_oe), .e_irq(m8_irq));

  apb_gpio_tb_model #(.N(32)) mdl32 (
    .clk(pclk), .rstn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .pin(gin),
    .e_prdata(m32_prdata), .e_pslverr(m32_err), .e_out(m32_out), .e_oe(m32_oe), .e_irq(m32_irq));

  // Clock
  initial begin
    pclk = 1'b0;
    forever #5 pclk = ~pclk;
  end

  // ---------------- checks (directed sequence) ----------------
  task automatic check32(input [31:0] got, input [31:0] exp);
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("apb_gpio_tb step %0d at %0t: got %h, expected %h", step, $time, got, exp);
      end
    end
  endtask

  task automatic check1(input got, input exp);
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("apb_gpio_tb step %0d at %0t: got %b, expected %b", step, $time, got, exp);
      end
    end
  endtask

  task check_pins(input [31:0] exp_out, input [31:0] exp_oe);
    begin
      check32(gout32, exp_out);
      check32({24'h0, gout8}, exp_out & 32'h0000_00FF);
      check32(goe32, exp_oe);
      check32({24'h0, goe8}, exp_oe & 32'h0000_00FF);
    end
  endtask

  task check_irq(input exp8, input exp32);
    begin
      check1(irq8, exp8);
      check1(irq32, exp32);
    end
  endtask

  // ---------------- monitor (every edge, against the models) ----------------
  task automatic mon32(input [31:0] got, input [31:0] exp, input integer what);
    begin
      if (got === exp) begin
        mpassed = mpassed + 1;
      end else begin
        mfailed = mfailed + 1;
        $error("apb_gpio_tb monitor %0d at %0t: DUT %h, model %h", what, $time, got, exp);
      end
    end
  endtask

  always @(posedge pclk) begin
    if (mon_en) begin
      mon32(prdata8, m8_prdata, 1);
      mon32({31'h0, pslverr8}, {31'h0, m8_err}, 2);
      mon32({31'h0, pready8}, 32'h0000_0001, 3);
      mon32({24'h0, gout8}, m8_out, 4);
      mon32({24'h0, goe8}, m8_oe, 5);
      mon32({31'h0, irq8}, {31'h0, m8_irq}, 6);
      mon32(prdata32, m32_prdata, 11);
      mon32({31'h0, pslverr32}, {31'h0, m32_err}, 12);
      mon32({31'h0, pready32}, 32'h0000_0001, 13);
      mon32(gout32, m32_out, 14);
      mon32(goe32, m32_oe, 15);
      mon32({31'h0, irq32}, {31'h0, m32_irq}, 16);
    end
  end

  // ---------------- APB manager ----------------
  // Write; the setup phase also drives the pins to 'pins'.
  task apb_write_pins(input [7:0] addr, input [31:0] data, input [3:0] strb,
                      input [31:0] pins, input exp_err);
    begin
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
      paddr = addr; pwdata = data; pstrb = strb; gin = pins;
      #1;
      check32(prdata8, 32'h0);  check32(prdata32, 32'h0);
      check1(pslverr8, 1'b0);   check1(pslverr32, 1'b0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready8, 1'b1);    check1(pready32, 1'b1);
      check1(pslverr8, exp_err); check1(pslverr32, exp_err);
      @(posedge pclk);
      #1;
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
    end
  endtask

  task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input exp_err);
    begin
      apb_write_pins(addr, data, strb, gin, exp_err);
    end
  endtask

  // Read; the setup phase also drives the pins to 'pins'.
  // exp32 is the N=32 value; the N=8 DUT is expected to return exp32 & 0xFF.
  task apb_read_pins(input [7:0] addr, input [31:0] pins, input [31:0] exp32, input exp_err);
    begin
      @(negedge pclk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
      paddr = addr; pwdata = 32'h0; pstrb = 4'h0; gin = pins;
      #1;
      check32(prdata8, 32'h0);  check32(prdata32, 32'h0);
      check1(pslverr8, 1'b0);   check1(pslverr32, 1'b0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready8, 1'b1);    check1(pready32, 1'b1);
      check1(pslverr8, exp_err); check1(pslverr32, exp_err);
      check32(prdata32, exp32);
      check32(prdata8, exp32 & 32'h0000_00FF);
      @(posedge pclk);
      #1;
      psel = 1'b0; penable = 1'b0;
    end
  endtask

  task apb_read(input [7:0] addr, input [31:0] exp32, input exp_err);
    begin
      apb_read_pins(addr, gin, exp32, exp_err);
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      @(negedge pclk);
      gin = v;
    end
  endtask

  // ---------------- directed sequence ----------------
  initial begin
    passed = 0;
    failed = 0;
    step   = 0;
    nonce  = {8*64{1'b0}};
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0; gin = 32'h0; a = 8'h00;

    // 1. Reset values
    step = 1;
    repeat (3) @(posedge pclk);
    #1;
    mon_en = 1'b1;
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);
    check1(pslverr8, 1'b0); check1(pslverr32, 1'b0);
    check32(prdata8, 32'h0); check32(prdata32, 32'h0);
    @(negedge pclk);
    presetn = 1'b1;
    a = 8'h00;
    for (k = 0; k < 9; k = k + 1) begin
      apb_read(a, 32'h0, 1'b0);
      a = a + 8'h04;
    end

    // 2. DATA_OUT with partial strobes, gpio_out
    step = 2;
    apb_write(8'h00, 32'hDEAD_BEEF, 4'hF, 1'b0);
    apb_read (8'h00, 32'hDEAD_BEEF, 1'b0);
    check_pins(32'hDEAD_BEEF, 32'h0);
    apb_write(8'h00, 32'h1234_5678, 4'b0101, 1'b0);
    apb_read (8'h00, 32'hDE34_BE78, 1'b0);
    apb_write(8'h00, 32'hFFFF_FFFF, 4'b0000, 1'b0);
    apb_read (8'h00, 32'hDE34_BE78, 1'b0);
    apb_write(8'h00, 32'h0000_0000, 4'b1010, 1'b0);
    apb_read (8'h00, 32'h0034_0078, 1'b0);
    check_pins(32'h0034_0078, 32'h0);

    // 3. DIR with partial strobes, gpio_oe
    step = 3;
    apb_write(8'h04, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h04, 32'hFFFF_FFFF, 1'b0);
    check_pins(32'h0034_0078, 32'hFFFF_FFFF);
    apb_write(8'h04, 32'h0000_A5A5, 4'b0011, 1'b0);
    apb_read (8'h04, 32'hFFFF_A5A5, 1'b0);
    apb_write(8'h04, 32'h0000_0000, 4'b1000, 1'b0);
    apb_read (8'h04, 32'h00FF_A5A5, 1'b0);
    check_pins(32'h0034_0078, 32'h00FF_A5A5);
    apb_read (8'h00, 32'h0034_0078, 1'b0);

    // 4. Detection enables and INTR_ENABLE: read/write with partial strobes
    step = 4;
    a = 8'h0C;
    for (k = 0; k < 5; k = k + 1) begin
      apb_write(a, 32'h89AB_CDEF, 4'hF, 1'b0);
      apb_read (a, 32'h89AB_CDEF, 1'b0);
      apb_write(a, 32'h0000_0000, 4'b0100, 1'b0);
      apb_read (a, 32'h8900_CDEF, 1'b0);
      apb_write(a, 32'h1111_1111, 4'b0000, 1'b0);
      apb_read (a, 32'h8900_CDEF, 1'b0);
      apb_write(a, 32'h0000_0000, 4'hF, 1'b0);
      apb_read (a, 32'h0000_0000, 1'b0);
      a = a + 8'h04;
    end
    // Low-level enables with pins low set status bits; clear them all.
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    check_irq(1'b0, 1'b0);

    // 5. DATA_IN: read only, one-edge sample latency
    step = 5;
    set_pins(32'h5A5A_C3C3);
    apb_read (8'h08, 32'h5A5A_C3C3, 1'b0);
    apb_write(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read (8'h08, 32'h5A5A_C3C3, 1'b0);
    apb_read (8'h00, 32'h0034_0078, 1'b0);
    apb_read (8'h04, 32'h00FF_A5A5, 1'b0);
    // pins change in the setup cycle; the access cycle already reads them
    apb_read_pins(8'h08, 32'h0F0F_1234, 32'h0F0F_1234, 1'b0);
    set_pins(32'h0000_0000);
    repeat (3) @(negedge pclk);
    apb_read (8'h08, 32'h0000_0000, 1'b0);

    // 6. PSLVERR policy: unaligned, out of range, aliases
    step = 6;
    apb_read(8'h01, 32'h0, 1'b1);
    apb_read(8'h02, 32'h0, 1'b1);
    apb_read(8'h03, 32'h0, 1'b1);
    apb_read(8'h05, 32'h0, 1'b1);
    apb_read(8'h22, 32'h0, 1'b1);
    apb_read(8'h24, 32'h0, 1'b1);
    apb_read(8'h28, 32'h0, 1'b1);
    apb_read(8'h3C, 32'h0, 1'b1);
    apb_read(8'h40, 32'h0, 1'b1);
    apb_read(8'h44, 32'h0, 1'b1);
    apb_read(8'h80, 32'h0, 1'b1);
    apb_read(8'hA0, 32'h0, 1'b1);
    apb_read(8'hFC, 32'h0, 1'b1);
    apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h1D, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hCC, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read (8'h00, 32'h0034_0078, 1'b0);
    apb_read (8'h04, 32'h00FF_A5A5, 1'b0);
    apb_read (8'h1C, 32'h0000_0000, 1'b0);
    apb_read (8'h0C, 32'h0000_0000, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    check_pins(32'h0034_0078, 32'h00FF_A5A5);
    check_irq(1'b0, 1'b0);

    // 7a. Rising edge: timing, fires once, partial clears, alias write
    step = 71;
    apb_write(8'h0C, 32'h8001_0003, 4'hF, 1'b0);
    apb_write(8'h1C, 32'h0000_0001, 4'hF, 1'b0);
    set_pins(32'h8001_0007);
    @(posedge pclk); #1;
    check_irq(1'b0, 1'b0);
    @(posedge pclk); #1;
    check_irq(1'b1, 1'b1);
    apb_read (8'h20, 32'h8001_0003, 1'b0);
    apb_write(8'hA0, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read (8'h20, 32'h8001_0003, 1'b0);
    apb_write(8'h20, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read (8'h20, 32'h8001_0002, 1'b0);
    apb_write(8'h20, 32'h8001_0002, 4'b0001, 1'b0);
    apb_read (8'h20, 32'h8001_0000, 1'b0);
    apb_write(8'h20, 32'h8001_0000, 4'b1100, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);

    // 7b. Falling edge, fires once
    step = 72;
    apb_write(8'h0C, 32'h0000_0000, 4'hF, 1'b0);
    apb_write(8'h10, 32'h8001_0003, 4'hF, 1'b0);
    set_pins(32'h0000_0000);
    apb_read (8'h20, 32'h8001_0003, 1'b0);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);

    // 7c. Both edges enabled, one-cycle pulse
    step = 73;
    apb_write(8'h10, 32'h0000_0010, 4'hF, 1'b0);
    apb_write(8'h0C, 32'h0000_0010, 4'hF, 1'b0);
    set_pins(32'h0000_0010);
    set_pins(32'h0000_0000);
    apb_read (8'h20, 32'h0000_0010, 1'b0);
    apb_write(8'h20, 32'h0000_0010, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    apb_write(8'h0C, 32'h0000_0000, 4'hF, 1'b0);
    apb_write(8'h10, 32'h0000_0000, 4'hF, 1'b0);

    // 7d. High level: sets again after a clear while the level holds
    step = 74;
    apb_write(8'h14, 32'h4000_0020, 4'hF, 1'b0);
    set_pins(32'h4000_0020);
    apb_read (8'h20, 32'h4000_0020, 1'b0);
    apb_write(8'h20, 32'h4000_0020, 4'hF, 1'b0);
    apb_read (8'h20, 32'h4000_0020, 1'b0);
    set_pins(32'h0000_0000);
    apb_read (8'h20, 32'h4000_0020, 1'b0);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    apb_write(8'h14, 32'h0000_0000, 4'hF, 1'b0);

    // 7e. Low level
    step = 75;
    apb_write(8'h18, 32'h0100_0040, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0100_0040, 1'b0);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0100_0040, 1'b0);
    set_pins(32'h0100_0040);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    apb_write(8'h18, 32'h0000_0000, 4'hF, 1'b0);

    // 7f. A clear on the edge a new rising edge is detected: detection wins
    step = 76;
    set_pins(32'h0000_0000);
    apb_write(8'h0C, 32'h0000_0003, 4'hF, 1'b0);
    set_pins(32'h0000_0003);
    apb_read (8'h20, 32'h0000_0003, 1'b0);
    check_irq(1'b1, 1'b1);
    set_pins(32'h0000_0000);
    repeat (3) @(negedge pclk);
    apb_write_pins(8'h20, 32'h0000_0003, 4'hF, 32'h0000_0001, 1'b0);
    apb_read (8'h20, 32'h0000_0001, 1'b0);
    apb_read (8'h20, 32'h0000_0001, 1'b0);
    check_irq(1'b1, 1'b1);

    // 7g. Interrupt mask
    step = 77;
    apb_write(8'h1C, 32'h0000_0000, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read (8'h20, 32'h0000_0001, 1'b0);
    set_pins(32'h0000_0003);
    apb_read (8'h20, 32'h0000_0003, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_write(8'h1C, 32'h0000_0002, 4'hF, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(8'h1C, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(8'h20, 32'h0000_0001, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read (8'h20, 32'h0000_0002, 1'b0);
    apb_write(8'h1C, 32'h0000_0003, 4'hF, 1'b0);
    check_irq(1'b1, 1'b1);
    apb_write(8'h20, 32'h0000_0002, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    // pin 31: exists only at N=32
    apb_write(8'h0C, 32'h8000_0000, 4'hF, 1'b0);
    apb_write(8'h1C, 32'h8000_0000, 4'hF, 1'b0);
    apb_read (8'h0C, 32'h8000_0000, 1'b0);
    apb_read (8'h1C, 32'h8000_0000, 1'b0);
    set_pins(32'h8000_0003);
    apb_read (8'h20, 32'h8000_0000, 1'b0);
    check_irq(1'b0, 1'b1);
    apb_write(8'h20, 32'h8000_0000, 4'hF, 1'b0);
    check_irq(1'b0, 1'b0);
    apb_read (8'h20, 32'h0000_0000, 1'b0);
    apb_write(8'h0C, 32'h0000_0000, 4'hF, 1'b0);
    apb_write(8'h1C, 32'h0000_0000, 4'hF, 1'b0);

    // 8. Reset again with state set
    step = 8;
    apb_write(8'h1C, 32'h0000_00FF, 4'hF, 1'b0);
    apb_write(8'h14, 32'h0000_0001, 4'hF, 1'b0);
    apb_read (8'h20, 32'h0000_0001, 1'b0);
    check_irq(1'b1, 1'b1);
    check_pins(32'h0034_0078, 32'h00FF_A5A5);
    @(negedge pclk);
    presetn = 1'b0;
    @(posedge pclk); #1;
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);
    repeat (2) @(posedge pclk);
    @(negedge pclk);
    presetn = 1'b1;
    apb_read(8'h00, 32'h0000_0000, 1'b0);
    apb_read(8'h04, 32'h0000_0000, 1'b0);
    apb_read(8'h08, 32'h8000_0003, 1'b0);
    apb_read(8'h0C, 32'h0000_0000, 1'b0);
    apb_read(8'h10, 32'h0000_0000, 1'b0);
    apb_read(8'h14, 32'h0000_0000, 1'b0);
    apb_read(8'h18, 32'h0000_0000, 1'b0);
    apb_read(8'h1C, 32'h0000_0000, 1'b0);
    apb_read(8'h20, 32'h0000_0000, 1'b0);
    check_pins(32'h0, 32'h0);
    check_irq(1'b0, 1'b0);

    // Verdict
    step = 9;
    repeat (2) @(posedge pclk);
    #1;
    mon_en = 1'b0;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed + mpassed, failed + mfailed);
    $finish;
  end

endmodule

// Reference model of interface_spec.md, written independently of the RTL:
// full-address decode, per-bit strobe expansion and detection.
module apb_gpio_tb_model #(
  parameter integer N = 8
) (
  input  wire        clk,
  input  wire        rstn,
  input  wire [7:0]  paddr,
  input  wire        psel,
  input  wire        penable,
  input  wire        pwrite,
  input  wire [31:0] pwdata,
  input  wire [3:0]  pstrb,
  input  wire [31:0] pin,
  output reg  [31:0] e_prdata,
  output reg         e_pslverr,
  output wire [31:0] e_out,
  output wire [31:0] e_oe,
  output wire        e_irq
);
  reg [31:0] m_out;
  reg [31:0] m_dir;
  reg [31:0] m_in;
  reg [31:0] m_prev;
  reg [31:0] m_rise;
  reg [31:0] m_fall;
  reg [31:0] m_high;
  reg [31:0] m_low;
  reg [31:0] m_en;
  reg [31:0] m_st;
  reg [31:0] rd;
  reg        hit;

  wire [31:0] exist;
  wire [31:0] lane;
  wire [31:0] det;

  genvar g;
  generate
    for (g = 0; g < 32; g = g + 1) begin : bits
      assign exist[g] = (g < N) ? 1'b1 : 1'b0;
      assign lane[g]  = exist[g] & pstrb[g / 8];
      assign det[g]   = exist[g] & (
                          (m_rise[g] &  m_in[g] & ~m_prev[g]) |
                          (m_fall[g] & ~m_in[g] &  m_prev[g]) |
                          (m_high[g] &  m_in[g]) |
                          (m_low[g]  & ~m_in[g]));
    end
  endgenerate

  wire        xfer = psel & penable;
  wire        wr   = xfer & pwrite;
  wire [31:0] clr  = (wr && (paddr == 8'h20)) ? (pwdata & lane) : 32'h0;

  function [31:0] mrg(input [31:0] old, input [31:0] nw, input [31:0] m);
    begin
      mrg = (old & ~m) | (nw & m);
    end
  endfunction

  always @(posedge clk) begin
    if (!rstn) begin
      m_out  <= 32'h0;
      m_dir  <= 32'h0;
      m_in   <= 32'h0;
      m_prev <= 32'h0;
      m_rise <= 32'h0;
      m_fall <= 32'h0;
      m_high <= 32'h0;
      m_low  <= 32'h0;
      m_en   <= 32'h0;
      m_st   <= 32'h0;
    end else begin
      m_in   <= pin & exist;
      m_prev <= m_in;
      m_st   <= (m_st & ~clr) | det;
      if (wr) begin
        case (paddr)
          8'h00:   m_out  <= mrg(m_out,  pwdata, lane);
          8'h04:   m_dir  <= mrg(m_dir,  pwdata, lane);
          8'h0C:   m_rise <= mrg(m_rise, pwdata, lane);
          8'h10:   m_fall <= mrg(m_fall, pwdata, lane);
          8'h14:   m_high <= mrg(m_high, pwdata, lane);
          8'h18:   m_low  <= mrg(m_low,  pwdata, lane);
          8'h1C:   m_en   <= mrg(m_en,   pwdata, lane);
          default: begin end
        endcase
      end
    end
  end

  always @* begin
    hit = 1'b1;
    case (paddr)
      8'h00:   rd = m_out;
      8'h04:   rd = m_dir;
      8'h08:   rd = m_in;
      8'h0C:   rd = m_rise;
      8'h10:   rd = m_fall;
      8'h14:   rd = m_high;
      8'h18:   rd = m_low;
      8'h1C:   rd = m_en;
      8'h20:   rd = m_st;
      default: begin rd = 32'h0; hit = 1'b0; end
    endcase
    e_prdata  = 32'h0;
    e_pslverr = 1'b0;
    if (xfer) begin
      if (!hit)
        e_pslverr = 1'b1;
      else if (pwrite && (paddr == 8'h08))
        e_pslverr = 1'b1;
      else if (!pwrite)
        e_prdata = rd;
    end
  end

  assign e_out = m_out;
  assign e_oe  = m_dir;
  assign e_irq = ((m_st & m_en) != 32'h0);

endmodule

`default_nettype wire
